#include <bits/stdc++.h>
using namespace std;

int n, m, maxm;
vector<vector<vector<int>>> dp;
vector<int> s;

int countBits(int num) {
    int count = 0;
    while (num > 0) {
        count += 1;
        num &= (num - 1);
    }
    return count;
}

bool isValid(int a, int b, int c) {
    int combined = ((maxm - 1) & (b | (b << 1) | (b >> 1) | a | c));
    return combined == maxm - 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    if (n < m) {
        int temp = n;
        n = m;
        m = temp;
    }
    maxm = 1 << m;
    dp.assign(n + 1, vector<vector<int>>(maxm, vector<int>(maxm, 100)));
    s.assign(maxm, 0);

    for (int i = 0; i < maxm; i++) {
        s[i] = countBits(i);
        dp[0][0][i] = 0;
    }

    for (int row = 1; row <= n; row++) {
        for (int prevMask = 0; prevMask < maxm; prevMask++) {
            for (int currMask = 0; currMask < maxm; currMask++) {
                for (int nextMask = 0; nextMask < maxm; nextMask++) {
                    if (dp[row - 1][prevMask][nextMask] != 100 && isValid(prevMask, nextMask, currMask)) {
                        dp[row][currMask][nextMask] = min(dp[row][currMask][nextMask], dp[row - 1][prevMask][nextMask] + s[nextMask]);
                    }
                }
            }
        }
    }

    int answer = INT_MAX;
    for (int i = 0; i < maxm; i++) {
        answer = min(dp[n][i][0], answer);
    }
    cout << n * m - answer << "\n";
    return 0;
}
